mapper.select:
SELECT user_id, COALESCE(SUM(amount), 0) AS amount
FROM billing_credit_lots
WHERE user_id IN
  #{uid}
  AND source = #{source}
GROUP BY user_id

SELECT id, user_id, source, source_priority, amount, remaining, frozen, expires_at,
       biz_type, biz_id, version, gmt_create
FROM billing_credit_lots

  user_id = #{userId}
  AND gmt_create >= #{createdFrom}
  AND gmt_create <= #{createdTo}

ORDER BY gmt_create DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM billing_credit_lots

  user_id = #{userId}
  AND gmt_create >= #{createdFrom}
  AND gmt_create <= #{createdTo}
